+    fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
+        match key {
+            UiKey::Char('h') | UiKey::Left => self.move_visual_cursor(0, -1),
+            UiKey::Char('l') | UiKey::Right => self.move_visual_cursor(0, 1),
+            UiKey::Char('k') | UiKey::Up => self.move_visual_cursor(-1, 0),
+            UiKey::Char('j') | UiKey::Down => self.move_visual_cursor(1, 0),
+            UiKey::Char('v') => self.set_visual_kind(VisualKind::Character),
+            UiKey::Char('V') => self.set_visual_kind(VisualKind::Line),
+            UiKey::Char(CTRL_V_CHAR) => self.set_visual_kind(VisualKind::Block),
+            UiKey::Char('y') => self.copy_visual_selection(),
+            UiKey::Char('Y') => {
+                self.set_visual_kind(VisualKind::Line);
+                self.copy_visual_selection();
+            }
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn start_visual_selection(&mut self, kind: VisualKind) {
+        let pane = self.focus;
+        let lines = self.selectable_lines_for_pane(pane);
+        if lines.is_empty() {
+            return;
+        }
+        let position = self.initial_visual_position(pane, &lines);
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: position,
+            cursor: position,
+        });
+        self.mode = UiMode::Command;
+        self.pending = None;
+    }
+
+    fn set_visual_kind(&mut self, kind: VisualKind) {
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.kind = kind;
+        } else {
+            self.start_visual_selection(kind);
+        }
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.selectable_lines_for_pane(selection.pane);
+        if lines.is_empty() {
+            return;
+        }
+
+        let current = clamp_text_position(selection.cursor, &lines);
+        let row = offset_usize(current.row, row_delta).min(lines.len().saturating_sub(1));
+        let column = offset_usize(current.column, column_delta)
+            .min(max_selectable_column(&lines[row]));
+
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.cursor = TextPosition { row, column };
+        }
+    }
+
+    fn copy_visual_selection(&mut self) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.selectable_lines_for_pane(selection.pane);
+        let copied = selected_text(selection, &lines);
+        self.store_clipboard(copied);
+        self.clear_visual_selection();
+    }
+
+    fn copy_current_line(&mut self) {
+        let pane = self.focus;
+        let lines = self.selectable_lines_for_pane(pane);
+        if lines.is_empty() {
+            return;
+        }
+        let position = self.initial_visual_position(pane, &lines);
+        let copied = lines.get(position.row).cloned().unwrap_or_default();
+        self.store_clipboard(copied);
+    }
+
+    fn store_clipboard(&mut self, text: String) {
+        let copied_chars = text.chars().count();
+        self.clipboard = Some(text);
+        self.pending_clipboard.set(true);
+        self.show_status_notice(
+            format!("copied {copied_chars} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn selectable_lines_for_pane(&self, pane: PaneFocus) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self
+                .left_widget_rows()
+                .into_iter()
+                .map(|line| line.text)
+                .collect(),
+            PaneFocus::Right => text_lines(&self.visual_right_content),
+        }
+    }
+
+    fn initial_visual_position(&self, pane: PaneFocus, lines: &[String]) -> TextPosition {
+        let position = match pane {
+            PaneFocus::Left => TextPosition {
+                row: self.control_selected,
+                column: 0,
+            },
+            PaneFocus::Right => self.visual_right_cursor,
+        };
+        clamp_text_position(position, lines)
+    }
+
+    fn visual_cursor_position(
+        &self,
+        selection: VisualSelection,
+        right_content: &str,
+    ) -> (u16, u16) {
+        match selection.pane {
+            PaneFocus::Left => {
+                let layout = self.layout();
+                let inner_width = usize::from(layout.left_width.saturating_sub(2).max(1));
+                let row = selection.cursor.row.saturating_add(2);
+                let column = selection.cursor.column.min(inner_width.saturating_sub(1)) + 2;
+                (
+                    row.min(usize::from(u16::MAX)) as u16,
+                    column.min(usize::from(u16::MAX)) as u16,
+                )
+            }
+            PaneFocus::Right => self.visual_right_cursor_position(selection.cursor, right_content),
+        }
+    }
+
+    fn visual_right_cursor_position(
+        &self,
+        cursor: TextPosition,
+        right_content: &str,
+    ) -> (u16, u16) {
+        let layout = self.layout();
+        let inner_width = layout.right_width.saturating_sub(2).max(1);
+        let lines = text_lines(right_content);
+        let cursor = clamp_text_position(cursor, &lines);
+        let previous_rows = lines[..cursor.row]
+            .iter()
+            .map(|line| visual_rows(line, inner_width))
+            .sum::<u16>();
+        let row = 2_u16
+            .saturating_add(previous_rows)
+            .saturating_add((cursor.column as u16) / inner_width);
+        let column = layout
+            .left_width
+            .saturating_add(2)
+            .saturating_add((cursor.column as u16) % inner_width);
+        (row, column)
+    }

